import sys
from datetime import datetime, timezone, timedelta


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string and return a timezone-aware datetime."""
    # Handle the 'Z' suffix (UTC)
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    # Parse using fromisoformat (Python 3.7+)
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        return None  # naive — skip
    return dt


def format_utc(dt):
    """Format a timezone-aware datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')


def main():
    with open(sys.argv[1], 'r') as f:
        data = json.load(f)

    as_of_raw = data.get('as_of')
    if as_of_raw is None:
        print(json.dumps([]))
        return

    as_of = parse_offset_aware(as_of_raw)
    if as_of is None:
        print(json.dumps([]))
        return

    reminders = data.get('reminders', [])
    result = []

    for r in reminders:
        # Skip completed reminders
        if r.get('completed', False):
            continue

        # Get due value — skip if missing, null, or naive
        due_raw = r.get('due')
        if due_raw is None:
            continue

        due = parse_offset_aware(due_raw)
        if due is None:
            continue  # naive due — skip

        # Check if due is AT OR BEFORE as_of (comparing actual instants)
        if due <= as_of:
            result.append({
                'id': r['id'],
                'title': r['title'],
                'due_utc': format_utc(due)
            })

